<!DOCTYPE html>
<html>
<head>
  <title>Billiards</title>
  <style>
    body { margin: 0; overflow: hidden; background-color: #333; }
    canvas { display: block; }
    .aim-line { position: absolute; z-index: 10; border: 1px dashed white; }
  </style>
</head>
<body>

<script>
  const canvas = document.createElement('canvas');
  document.body.appendChild(canvas);

  const sim = {
    W: 800,
    H: 600,
    R: 25,
    balls: [],
    paused: true,

    reset: function(balls) {
      this.balls = balls.map(ball => ({
        x: ball.x || this.W / 2,
        y: ball.y || this.H / 2,
        vx: ball.vx || 0,
        vy: ball.vy || 0,
        cue: ball.cue || false,
        potted: false
      }));
    },

    step: function(dt) {
      if (!this.paused) {
        for (let i = 0; i < this.balls.length; i++) {
          const ball = this.balls[i];

          ball.x += ball.vx * dt;
          ball.y += ball.vy * dt;

          // Bounce off walls
          if (ball.x + this.R > this.W || ball.x - this.R < 0) ball.vx = -ball.vx;
          if (ball.y + this.R > this.H || ball.y - this.R < 0) ball.vy = -ball.vy;

          // Ball-to-ball collisions
          for (let j = i + 1; j < this.balls.length; j++) {
            const otherBall = this.balls[j];
             if (ball === otherBall) continue;

            const dx = otherBall.x - ball.x;
            const dy = otherBall.y - ball.y;
            const distSq = dx * dx + dy * dy;
            const ballRadiusSum = this.R * 2;

            if (distSq < (this.R + otherBall.R) * (this.R + otherBall.R)) {  // Collision detected

              const nx = dx / Math.sqrt(distSq);
              const ny = dy / Math.sqrt(distSq);

              const dotProduct = nx * otherBall.vx + ny * otherBall.vy;

              if (dotProduct > 0) {
                const restitution = 0.8;  // Adjust for bounciness

                let relativeVelocity = nx * ball.vx + ny * ball.vy - dotProduct;

                let impulse = restitution * dotProduct / (1 + restitution);
                ball.vx -= impulse * nx;
                ball.vy -= impulse * ny;
                otherBall.vx += impulse * nx;
                otherBall.vy += impulse * ny;
              }
            }
          }

          // Check for pockets
          if (ball.x >= this.W - this.R && ball.y >= this.R)  this.balls[i].potted = true;
          if (ball.x <= this.R && ball.y >= this.R) this.balls[i].potted = true;
          if (ball.x >= this.W - this.R && ball.y <= this.H - this.R) this.balls[i].potted = true;
          if (ball.x <= this.R && ball.y <= this.H - this.R) this.balls[i].potted = true;
          if (ball.x >= this.W / 2 - this.R && ball.y <= this.H / 2 - this.R) this.balls[i].potted = true;
          if (ball.x <= this.W / 2 + this.R && ball.y <= this.H / 2 - this.R) this.balls[i].potted = true;
          if (ball.x >= this.W / 2 - this.R && ball.y >= this.H / 2 + this.R)  this.balls[i].potted = true;
          if (ball.x <= this.W / 2 + this.R && ball.y >= this.H / 2 + this.R)  this.balls[i].potted = true;

        }
      }
    },

    state: function() {
      return this.balls.map(ball => ({
        x: ball.x,
        y: ball.y,
        vx: ball.vx,
        vy: ball.vy,
        potted: ball.potted,
        cue: ball.cue
      }));
    },

    shoot: function(vx, vy) {
      this.paused = false;  // Start the animation after a shot
      const cueBall = this.balls.find(b => b.cue);
      if (cueBall) {
        cueBall.vx = vx;
        cueBall.vy = vy;
      }

    },

    pause: function() {
      this.paused = true;
    },

    resume: function() {
      this.paused = false;
    }
  };

  sim.reset([{ x: 200, y: 300, vx: 1, vy: 2, cue: true },
                { x: 500, y: 300, vx: -1, vy: 2, cue: false },
                { x: 350, y: 450, vx: 0.5, vy: -1, cue: false },
                { x: 650, y: 450, vx: -0.5, vy: -1, cue: false }]);

  let dt = 0.02;
  let lastTime = 0;

  function animate() {
    requestAnimationFrame(animate);

    const now = Date.now();
    const elapsedTime = (now - lastTime) / 1000;
    sim.step(elapsedTime);

    lastTime = now;

    let state = sim.state();
    draw(state);
  }


  function draw(state) {
    if (!canvas.getContext) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, sim.W, sim.H);

    // Draw the table (simplified)
    ctx.fillStyle = '#808080'; // Grey
    ctx.fillRect(0, 0, sim.W, sim.H);

    // Draw pockets
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(sim.W / 2 - sim.R, sim.R, sim.R, 0, 2 * Math.PI);
    ctx.fill();
    ctx.arc(sim.W - sim.R, sim.H / 2 - sim.R, sim.R, 0, 2 * Math.PI);
    ctx.fill();
    ctx.arc(sim.R, sim.H / 2 - sim.R, sim.R, 0, 2 * Math.PI);
    ctx.fill();
    ctx.arc(sim.W / 2 - sim.R, sim.H - sim.R, sim.R, 0, 2 * Math.PI);
    ctx.fill();

     // Draw aim line
      ctx.beginPath();
      ctx.moveTo(0, sim.H / 2);
      ctx.lineTo(sim.W, sim.H / 2);
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 2;
      ctx.stroke();

    // Draw balls
    state.forEach(ball => {
      if (!ball.potted) {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, sim.R, 0, 2 * Math.PI);
        ctx.fillStyle = 'white';
        ctx.fill();
      }
    });

     // Draw cue ball (highlighted)
     if (state.find(b => b.cue)) {
       const cueBall = state.find(b => b.cue);
       ctx.beginPath();
       ctx.arc(cueBall.x, cueBall.y, sim.R - 10, 0, 2 * Math.PI);
       ctx.fillStyle = 'yellow';
       ctx.fill();
     }
  }

  animate();

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    let mouseX = e.clientX - rect.left;
    let mouseY = e.clientY - rect.top;

    if (mouseX > rect.left && mouseX < rect.right && mouseY > rect.top && mouseY < rect.bottom) {
      const cueBall = sim.balls.find(b => b.cue);
      if (cueBall) {
        sim.shoot(mouseX - rect.left - sim.W / 2, mouseY - rect.top - sim.H / 2);
      }
    }
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    let mouseX = e.clientX - rect.left;
    let mouseY = e.clientY - rect.top;

    if (mouseX > rect.left && mouseX < rect.right && mouseY > rect.top && mouseY < rect.bottom) {
      const cueBall = sim.balls.find(b => b.cue);
       if (cueBall) {
           sim.shoot(mouseX - rect.left - sim.W / 2, mouseY - rect.top - sim.H / 2);
       }
    }

  });
</script>

</body>
</html>
